-- 003_seed_states_and_cities.sql
-- Complete 28 States, 8 Union Territories with Capitals and Major Cities of India

-- Ensure state type / capital support on states table if desired, or keep backward compatible
ALTER TABLE states ADD COLUMN IF NOT EXISTS type TEXT DEFAULT 'State';
ALTER TABLE states ADD COLUMN IF NOT EXISTS capital TEXT;

-- Insert / Update all 28 States and 8 Union Territories

-- Create cities table if not exists
CREATE TABLE IF NOT EXISTS cities (
  id          SERIAL PRIMARY KEY,
  name        TEXT NOT NULL,
  state_id    INT REFERENCES states(id) ON DELETE CASCADE,
  is_capital  BOOLEAN DEFAULT FALSE,
  location    geometry(Point, 4326) NOT NULL,
  created_at  TIMESTAMPTZ DEFAULT now(),
  UNIQUE(name, state_id)
);
CREATE INDEX IF NOT EXISTS idx_cities_location ON cities USING GIST (location);

